import org.apache.commons.math3.distribution.WeibullDistribution;

public class SeñalRadio {
  public static void main(String[] args) {
      // En Java Commons Math no existe 'RayleighDistribution'. 
      // Tienes que usar la distribución generalizada Weibull para simularla.
      WeibullDistribution dist = new WeibullDistribution(2.0, 2.0 * Math.sqrt(2));

      double prediccion = dist.sample();
      System.out.println(prediccion);
  }
}
